-- Exportación del sistema de citas de consultas externas (a 2026-11-06, fin de la jornada). Carga: sqlite3 booking.db < este fichero. Fechas AAAA-MM-DD, horas HH:MM.
-- 
-- departments: códigos y nombres de especialidad
-- languages: códigos y nombres de idioma
-- doctors: médicos
-- doctor_languages: los idiomas que habla cada médico
-- weekly_sessions: consultas semanales (weekday 1 = lunes; session AM mañana / PM tarde; huecos de 20 minutos)
-- clinic_sessions: el calendario de consultas del 2026-10-12 al 2026-11-20 (sin cambios por festivos)
-- requests: solicitudes de cita (las atendidas desde el 12 de octubre y las recibidas antes del 6 de noviembre que esperan o están citadas para una fecha posterior)
-- request_notes: notas del personal sobre las solicitudes
-- appointments: citas: acudió, no acudió, anulada por el paciente, y citadas a partir del 9 de noviembre
-- cancellations: citas anuladas por el paciente
-- attendance: asistencia (attended 1 = acudió, 0 = no acudió)
-- waitlist_history: entradas y salidas de la lista de espera (removed_on vacío: sigue esperando)
-- status_reports: la tabla de estado por especialidad (la del día piloto, del programa piloto)
BEGIN TRANSACTION;
CREATE TABLE "departments" ("department_code" TEXT PRIMARY KEY, "name" TEXT);
CREATE TABLE "languages" ("language_code" TEXT PRIMARY KEY, "name" TEXT);
CREATE TABLE "doctors" ("doctor_id" TEXT PRIMARY KEY, "name" TEXT, "department_code" TEXT);
CREATE TABLE "doctor_languages" ("doctor_id" TEXT, "language_code" TEXT);
CREATE TABLE "weekly_sessions" ("doctor_id" TEXT, "weekday" INTEGER, "weekday_name" TEXT, "session" TEXT, "start_time" TEXT, "end_time" TEXT, "slot_minutes" INTEGER);
CREATE TABLE "clinic_sessions" ("doctor_id" TEXT, "date" TEXT, "session" TEXT, "start_time" TEXT, "end_time" TEXT, "slot_minutes" INTEGER);
CREATE TABLE "requests" ("request_id" TEXT PRIMARY KEY, "patient_id" TEXT, "received" TEXT, "department_code" TEXT, "visit_type" TEXT, "previous_doctor" TEXT, "urgency" TEXT, "triage_note" TEXT, "preferred_language" TEXT, "earliest_date" TEXT, "referral_valid_until" TEXT, "pre_visit_test" TEXT);
CREATE TABLE "request_notes" ("request_id" TEXT, "author_role" TEXT, "text" TEXT);
CREATE TABLE "appointments" ("request_id" TEXT, "patient_id" TEXT, "doctor_id" TEXT, "date" TEXT, "start" TEXT, "slots" INTEGER, "test_date" TEXT, "booked_on" TEXT, "status" TEXT);
CREATE TABLE "cancellations" ("request_id" TEXT, "patient_id" TEXT, "doctor_id" TEXT, "date" TEXT, "start" TEXT, "cancelled_on" TEXT, "cancelled_by" TEXT);
CREATE TABLE "attendance" ("date" TEXT, "request_id" TEXT, "patient_id" TEXT, "doctor_id" TEXT, "start" TEXT, "attended" INTEGER);
CREATE TABLE "waitlist_history" ("request_id" TEXT, "department_code" TEXT, "added_on" TEXT, "removed_on" TEXT, "removal_reason" TEXT);
CREATE TABLE "status_reports" ("report_date" TEXT, "department_code" TEXT, "free_slots" INTEGER, "held_back" INTEGER, "waitlist" INTEGER, "produced_by" TEXT);
COMMIT;
